'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/timepicker/md-gb-time-picker.js';
import {TimePickerElement} from '@material/web/labs/gb/components/timepicker/time-picker-element.js';

/**
 * A Material Design time picker component. Wraps <md-gb-time-picker>.
 * Docs: https://material-web.dev/3.0/components/time-picker/
 */
export const MdTimePicker = createComponent({
  react: React,
  tagName: 'md-gb-time-picker',
  elementClass: TimePickerElement,
  events: {
    onCancel: 'cancel' as EventName<Event>,
    onChange: 'change' as EventName<Event>,
    onClose: 'close' as EventName<Event>,
    onInput: 'input' as EventName<Event>,
    onOpen: 'open' as EventName<Event>,
  },
});

export type MdTimePickerProps = React.ComponentProps<typeof MdTimePicker>;
